#define MAX_STEPS 100
#define MAX_DIST 100.0
#define SURF_DIST 0.001
#define PHI 1.618033988749895
#define PI 3.14159265359

float sphereSDF(vec3 p, float r) {
    return length(p) - r;
}

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float sdCapsule(vec3 p, vec3 a, vec3 b, float r) {
    vec3 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

float animatedTesseract(vec3 p) {
    float t = iTime * 0.9;

    vec3 pp = p;
    pp.xy *= rot2D(t * 0.5);
    pp.xz *= rot2D(t * 0.3);
    pp.yz *= rot2D(t * 0.4);

    float scale = 0.5;

    vec3 v0 = vec3(-1.0, -1.0, -1.0) * scale;
    vec3 v1 = vec3( 1.0, -1.0, -1.0) * scale;
    vec3 v2 = vec3( 1.0,  1.0, -1.0) * scale;
    vec3 v3 = vec3(-1.0,  1.0, -1.0) * scale;
    vec3 v4 = vec3(-1.0, -1.0,  1.0) * scale;
    vec3 v5 = vec3( 1.0, -1.0,  1.0) * scale;
    vec3 v6 = vec3( 1.0,  1.0,  1.0) * scale;
    vec3 v7 = vec3(-1.0,  1.0,  1.0) * scale;

    float w = sin(t) * 0.3 + 0.5;
    float innerScale = scale * 0.5;
    vec3 vi0 = v0 * w + vec3(-1.0, -1.0, -1.0) * innerScale;
    vec3 vi1 = v1 * w + vec3( 1.0, -1.0, -1.0) * innerScale;
    vec3 vi2 = v2 * w + vec3( 1.0,  1.0, -1.0) * innerScale;
    vec3 vi3 = v3 * w + vec3(-1.0,  1.0, -1.0) * innerScale;
    vec3 vi4 = v4 * w + vec3(-1.0, -1.0,  1.0) * innerScale;
    vec3 vi5 = v5 * w + vec3( 1.0, -1.0,  1.0) * innerScale;
    vec3 vi6 = v6 * w + vec3( 1.0,  1.0,  1.0) * innerScale;
    vec3 vi7 = v7 * w + vec3(-1.0,  1.0,  1.0) * innerScale;

    float d = MAX_DIST;
    float r = 0.03;

    d = min(d, sdCapsule(pp, v0, v1, r));
    d = min(d, sdCapsule(pp, v1, v2, r));
    d = min(d, sdCapsule(pp, v2, v3, r));
    d = min(d, sdCapsule(pp, v3, v0, r));
    d = min(d, sdCapsule(pp, v4, v5, r));
    d = min(d, sdCapsule(pp, v5, v6, r));
    d = min(d, sdCapsule(pp, v6, v7, r));
    d = min(d, sdCapsule(pp, v7, v4, r));
    d = min(d, sdCapsule(pp, v0, v4, r));
    d = min(d, sdCapsule(pp, v1, v5, r));
    d = min(d, sdCapsule(pp, v2, v6, r));
    d = min(d, sdCapsule(pp, v3, v7, r));

    d = min(d, sdCapsule(pp, vi0, vi1, r));
    d = min(d, sdCapsule(pp, vi1, vi2, r));
    d = min(d, sdCapsule(pp, vi2, vi3, r));
    d = min(d, sdCapsule(pp, vi3, vi0, r));
    d = min(d, sdCapsule(pp, vi4, vi5, r));
    d = min(d, sdCapsule(pp, vi5, vi6, r));
    d = min(d, sdCapsule(pp, vi6, vi7, r));
    d = min(d, sdCapsule(pp, vi7, vi4, r));
    d = min(d, sdCapsule(pp, vi0, vi4, r));
    d = min(d, sdCapsule(pp, vi1, vi5, r));
    d = min(d, sdCapsule(pp, vi2, vi6, r));
    d = min(d, sdCapsule(pp, vi3, vi7, r));

    d = min(d, sdCapsule(pp, v0, vi0, r));
    d = min(d, sdCapsule(pp, v1, vi1, r));
    d = min(d, sdCapsule(pp, v2, vi2, r));
    d = min(d, sdCapsule(pp, v3, vi3, r));
    d = min(d, sdCapsule(pp, v4, vi4, r));
    d = min(d, sdCapsule(pp, v5, vi5, r));
    d = min(d, sdCapsule(pp, v6, vi6, r));
    d = min(d, sdCapsule(pp, v7, vi7, r));

    return d;
}

float pearlString(vec3 p) {
    float t = iTime * 0.3;
    float pearls = MAX_DIST;
    float numPearls = 33.0;

    for(float i = 0.0; i < numPearls; i++) {
        float fi = i / numPearls;

        float theta = fi * 8.0 * PI - t * 0.5;
        float zPos = mix(-2.0, 8.0, fi);
        float radius = exp(fi * 1.2) * 0.2;

        vec3 center = vec3(
            tan(theta) * radius,
            sin(theta) * radius,
            zPos
        );

        float baseSize = mix(0.02, 1.0, pow(fi, 2.0));
        float sizeMod = smoothstep(-2.0, 8.0, center.z);
        float pearlSize = baseSize * (1.0 + sizeMod * 3.0);

        float pearl = sphereSDF(p - center, pearlSize);
        float distanceGlow = smoothstep(0.0, 1.0, fi) * 0.15;
        pearl -= distanceGlow;

        pearls = min(pearls, pearl);
    }

    return pearls;
}

vec3 getPearlColor(vec3 p) {
    float t = iTime * 0.3;

    float angle = atan(p.y, p.x);
    float radius = length(p.xy);
    float height = p.z;

    float cycleFactor = angle / (2.0 * PI) + radius * 0.2 + height * 0.1 + t * 0.2;

    vec3 color1 = vec3(0.3, 0.6, 1.0);
    vec3 color2 = vec3(0.2, 0.9, 1.0);
    vec3 color3 = vec3(0.7, 0.3, 1.0);
    vec3 color4 = vec3(1.0, 0.4, 0.8);

    float t1 = sin(cycleFactor * PI * 2.0) * 0.5 + 0.5;
    float t2 = sin(cycleFactor * PI * 2.0 + PI * 0.5) * 0.5 + 0.5;
    float t3 = sin(cycleFactor * PI * 2.0 + PI) * 0.5 + 0.5;

    vec3 iridColor = mix(
        mix(color1, color2, t1),
        mix(color3, color4, t2),
        t3
    );

    float shimmer = sin(radius * 8.0 + angle * 4.0 + t * 2.0) * 0.15 + 0.95;
    float brightBoost = smoothstep(-2.0, 8.0, p.z) * 0.5 + 1.0;

    return iridColor * shimmer * brightBoost;
}

float sceneSDF(vec3 p) {
    return min(pearlString(p), animatedTesseract(p));
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    float d = sceneSDF(p);
    return normalize(vec3(
        sceneSDF(p + e.xyy) - d,
        sceneSDF(p + e.yxy) - d,
        sceneSDF(p + e.yyx) - d
    ));
}

float rayMarch(vec3 ro, vec3 rd) {
    float d0 = 0.0;

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * d0;
        float ds = sceneSDF(p);
        d0 += ds;
        if(ds < SURF_DIST || d0 > MAX_DIST) break;
    }

    return d0;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0, 0.0, -3.0);
    vec3 rd = normalize(vec3(uv, 1.2));

    float t = iTime * 0.3;

    ro.xy *= rot2D(sin(t * 0.5) * 0.2);
    rd.xy *= rot2D(sin(t * 0.5) * 0.2);

    float d = rayMarch(ro, rd);
    vec3 col = vec3(0.0);

    if(d < MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = getNormal(p);

        vec3 lightPos = vec3(2.0 * cos(t), 2.0 * sin(t), -2.0);
        vec3 l = normalize(lightPos - p);
        float diff = max(0.0, dot(n, l)) * 0.6 + 0.4;

        vec3 tesseractCol = vec3(0.1, 0.4, 1.0) * (1.0 + 0.5 * sin(t * 2.0));

        if(pearlString(p) < animatedTesseract(p)) {
            vec3 baseCol = getPearlColor(p);
            float fresnel = pow(1.0 - max(0.0, dot(n, -rd)), 3.0);
            vec3 reflection = reflect(rd, n);
            float specRef = pow(max(0.0, dot(reflection, l)), 32.0);

            col = mix(baseCol * 0.8, vec3(1.0), fresnel * 0.7);
            col += specRef * 0.6;

            float depth = length(p - ro);
            float depthBright = exp(-depth * 0.1) * 0.5 + 0.8;
            col *= depthBright;
        } else {
            col = tesseractCol;
        }

        col *= diff;

        float glow = 0.2 / (0.1 + d * d * 0.1);
        col += col * glow;
    }

    col = mix(col, vec3(0.0), 1.0 - exp(-d * 0.15));

    fragColor = vec4(col, 1.0);
}
